93	/**
94	 * Molecule — the product-card media block: a single image, a hover-swap pair, or a full
95	 * scroll-snap gallery with desktop arrows / touch slide-indicator, plus the wishlist-remove
96	 * overlay slot. Figma "Image Group" component set, node 40002742:46323.
97	 *
98	 * Touch paging is native CSS scroll-snap at every breakpoint; arrows are a progressive
99	 * enhancement over the same scroll container, never a second, independent mechanism. Arrows and
100	 * the slide indicator are mutually exclusive by pointer capability
101	 * (`(hover: hover) and (pointer: fine)`) and never both interactively visible at once. Both
102	 * exist in the DOM at all times and are gated by the recipe's own CSS media query rather than a
103	 * JS `window.matchMedia` check — matching the "keep in DOM, hide via CSS" precedent
104	 * `ZimmColourSwatchGroup` already uses for its off-page swatches — so server and client render
105	 * identically (no hydration mismatch) and neither affordance depends on `matchMedia`, which
106	 * jsdom (this component's own Vitest environment) does not implement.
107	 *
108	 * A third, always-available operability layer sits underneath both visual affordances: the
109	 * scroll container itself is keyboard-focusable and handles ArrowLeft/ArrowRight directly
110	 * whenever there is more than one slide, regardless of pointer capability or `showControls` —
111	 * a hover-incapable pointer previously had no way to page the gallery via keyboard at all
112	 * (WCAG 2.1.1), since the arrows are `display:none` there and the indicator has no focusable
113	 * content. See `canNavigateByKeyboard` / `handleScrollContainerKeyDown` below.
114	 */
115	export const ZimmProductCardMedia = ({
116	  primaryImage,
117	  hoverImage,
118	  images,
119	  swapOnHover,
120	  showControls,
121	  badge,
122	  onRemove,
123	  removeLabel,
124	  priority,
125	}: ZimmProductCardMediaProps) => {
126	  const intl = useIntl();
127	  const styles = useMultiStyleConfig(ZIMM_PRODUCT_CARD_MEDIA_RECIPE, {});
128	
129	  // >1 entries takes over as the full slide list; 0 or 1 behaves like no gallery at all (see
130	  // the `images` prop's own JSDoc for why hover-swap and the gallery don't combine).
131	  const gallery = images && images.length > 1 ? images : undefined;
132	  const slideImages = gallery ?? [primaryImage];
133	  const totalSlides = slideImages.length;
134	  const showHoverSwap = swapOnHover && Boolean(hoverImage) && !gallery;
135	  const canPage = totalSlides > 1 && showControls;
136	  // Keyboard operability is independent of `showControls` — deliberately not folded into
137	  // `canPage` above (WCAG 2.1.1): a hover-incapable pointer (a touchscreen with a physical
138	  // keyboard attached, switch access, or a desktop browser reporting `hover:none`) has the
139	  // arrows hidden by the recipe's own media query and the indicator has no focusable content,
140	  // so this is the only paging affordance such a user has, regardless of `showControls`.
141	  const canNavigateByKeyboard = totalSlides > 1;
142	
143	  // Single piece of state, per this codebase's extract-to-hook threshold
144	  // (.claude/rules/components.md). Kept inline — including the scroll-tracking and
145	  // index-clamping effects below — rather than pulled into a useProductCardMediaScroll hook,
146	  // because this build step's file manifest is limited to this component's own 4 files; a hook
147	  // would be a 5th file outside that scope.
148	  const [currentIndex, setCurrentIndex] = useState(0);
149	  const scrollContainerRef = useRef<HTMLDivElement>(null);
150	
151	  const scrollToIndex = (index: number) => {
152	    const container = scrollContainerRef.current;
153	    if (!container || typeof container.scrollTo !== 'function') return;
154	    // clientWidth is 0 under jsdom (no real layout) — the call still fires with a plausible
155	    // {left, behavior} shape, which is what this component's own Vitest suite asserts; a real
156	    // browser reports a real width so the requested slide scrolls fully into view.
157	    container.scrollTo({ left: index * container.clientWidth, behavior: 'smooth' });
158	  };
159	
160	  const goToRelativeSlide = (delta: 1 | -1) => {
161	    if (totalSlides <= 1) return;
162	    const next = (currentIndex + delta + totalSlides) % totalSlides;
163	    setCurrentIndex(next);
164	    scrollToIndex(next);
165	  };
166	
167	  // Re-clamps currentIndex whenever the slide count shrinks while this instance stays mounted
168	  // (e.g. a colour-variant swap that reduces the gallery from 3 images to 2) — same "clamp to
169	  // the highest valid index" precedent as ZimmColourSwatchGroup's own page-clamp effect
170	  // (../zimmColourSwatchGroup/index.tsx:75-84). Without this, currentIndex stays at the stale,
171	  // out-of-range value: ZimmSlideIndicator's own display-side clamp masks it visually right
172	  // after the shrink, but goToRelativeSlide's modulo arithmetic above still computes from the
173	  // stale, unclamped state, so the very next Next/Previous click is a silent no-op.
174	  useEffect(() => {
175	    setCurrentIndex((index) => Math.min(index, totalSlides - 1));
176	  }, [totalSlides]);
177	
178	  // Arrow-key paging on the scroll container itself, reachable regardless of pointer
179	  // capability — additive to, and independent of, the hover-capable-only arrows and the
180	  // touch-only indicator above (see canNavigateByKeyboard's own comment for why). Same
181	  // "check the key, then preventDefault" idiom as ZimmColourSwatchGroup's own
182	  // handleSwatchesKeyDown (../zimmColourSwatchGroup/index.tsx:109-111).
183	  const handleScrollContainerKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
184	    if (!['ArrowLeft', 'ArrowRight'].includes(event.key)) return;
185	    event.preventDefault();
