193	  // lags on an unsupported browser, a minor, graceful degradation rather than a broken
194	  // interaction.
195	  useEffect(() => {
196	    const container = scrollContainerRef.current;
197	    if (!container || totalSlides <= 1) return undefined;
198	
199	    const handleScrollEnd = () => {
200	      const slideWidth = container.clientWidth || 1;
201	      const nearest = Math.round(container.scrollLeft / slideWidth);
202	      setCurrentIndex(Math.min(Math.max(nearest, 0), totalSlides - 1));
203	    };
204	
205	    container.addEventListener('scrollend', handleScrollEnd);
206	    return () => container.removeEventListener('scrollend', handleScrollEnd);
207	  }, [totalSlides]);
208	
209	  // Non-primary images are always lazy; only the first slide's own base image can opt into
210	  // eager loading via `priority`. See that prop's own JSDoc for the default-to-lazy reasoning.
211	  const imageLoadingProps = (isPrimaryPosition: boolean): { loading?: 'lazy'; decoding: 'async' } =>
212	    isPrimaryPosition && priority ? { decoding: 'async' } : { loading: 'lazy', decoding: 'async' };
213	
214	  const hasUsableRemoveLabel = typeof removeLabel === 'string' && removeLabel.trim().length > 0;
215	  const showRemove = Boolean(onRemove) && hasUsableRemoveLabel;
216	  const hasBadge = typeof badge === 'string' && badge.trim().length > 0;
217	
218	  return (
219	    <chakra.div __css={styles.root} data-card-slot="media">
220	      <chakra.div
221	        ref={scrollContainerRef}
222	        __css={styles.scrollContainer}
223	        data-testid="card-media-scroll"
224	        role={canNavigateByKeyboard ? 'group' : undefined}
225	        aria-label={canNavigateByKeyboard ? intl.formatMessage(messages.galleryLabel) : undefined}
226	        tabIndex={canNavigateByKeyboard ? 0 : undefined}
227	        onKeyDown={canNavigateByKeyboard ? handleScrollContainerKeyDown : undefined}
228	      >
229	        {slideImages.map((image, index) => {
230	          const isPrimaryPosition = index === 0;
231	
232	          if (isPrimaryPosition && showHoverSwap && hoverImage) {
233	            return (
234	              <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
235	                <chakra.img
236	                  src={image.src}
237	                  alt={image.alt}
238	                  data-role="hover-base"
239	                  __css={styles.hoverSwapBase}
240	                  {...imageLoadingProps(true)}
241	                />
242	                <chakra.img
243	                  src={hoverImage.src}
244	                  alt={hoverImage.alt}
245	                  data-role="hover-overlay"
246	                  __css={styles.hoverSwapOverlay}
247	                  {...imageLoadingProps(false)}
248	                />
249	              </chakra.div>
250	            );
251	          }
252	
253	          return (
254	            <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
255	              <chakra.img
256	                src={image.src}
257	                alt={image.alt}
258	                __css={styles.image}
259	                {...imageLoadingProps(isPrimaryPosition)}
260	              />
261	            </chakra.div>
262	          );
263	        })}
264	      </chakra.div>
265	
266	      {hasBadge && (
267	        <chakra.div __css={styles.badge} data-card-slot="badge">
268	          <chakra.span __css={styles.badgeLabel}>{badge}</chakra.span>
269	        </chakra.div>
270	      )}
271	
272	      {showRemove && (
273	        <chakra.button
274	          type="button"
275	          __css={styles.close}
276	          data-card-slot="close"
277	          aria-label={removeLabel}
278	          onClick={onRemove}
279	        >
280	          <CloseIcon aria-hidden boxSize="var(--zimm-icon-size-md)" />
281	        </chakra.button>
282	      )}
283	
284	      {canPage && (
285	        <chakra.div __css={styles.carousel} data-card-slot="carousel">
286	          <chakra.button
287	            type="button"
288	            __css={styles.arrowButton}
289	            aria-label={intl.formatMessage(messages.previousImage)}
290	            onClick={() => goToRelativeSlide(-1)}
291	          >
292	            <ChevronLeftIcon aria-hidden />
293	          </chakra.button>
294	          <chakra.button
295	            type="button"
296	            __css={styles.arrowButton}
297	            aria-label={intl.formatMessage(messages.nextImage)}
298	            onClick={() => goToRelativeSlide(1)}
299	          >
300	            <ChevronRightIcon aria-hidden />
301	          </chakra.button>
302	        </chakra.div>
303	      )}
304	
305	      {totalSlides > 1 && (
306	        <chakra.div __css={styles.indicatorWrapper} data-card-slot="indicator">
307	          <ZimmSlideIndicator count={totalSlides} activeIndex={currentIndex} />
308	        </chakra.div>
309	      )}
310	    </chakra.div>
311	  );
312	};
313	
314	export default ZimmProductCardMedia;
